                "loss": losses,
                "accuracy": accuracy,
            },
        }
        payload = (_dump_compact(artifact) + "\n").encode("utf-8")
        _atomic_write_output(output_path, payload)
    except (_TrainDataError, ValueError, TypeError, OSError):
        return 1
    return 0


